ValidationRule.errorConditionFormula:
AND(
    /* Exceções de quem pode editar mesmo fechado */
    NOT(
        OR(
            $Profile.Name = "Mais Polimeros Admin",
            $Profile.Name = "Mais Polimeros Admin - sMFA",
            $Profile.Name = "Administrador do sistema",
            $Profile.Name = "Integrador"
        )
    ),

    NOT($User.ByPassVR__c),

    ByPassVR__c = false,
    NOT(ISCHANGED(ByPassVR__c)),

    /* Deixa Flows/Processos automáticos passarem */
    TEXT($User.UserType) <> "AutomatedProcess",

    /* Libera quando o status for alterado para Perdido */
    NOT(
        AND(
            ISCHANGED(StageName),
            OR(
                TEXT(StageName) = "Closed Lost",
                TEXT(StageName) = "Fechado Perdido"
            )
        )
    ),

    /* Se o estágio ANTERIOR já era fechado */
    OR(
        TEXT(PRIORVALUE(StageName)) = "Closed Won",
        TEXT(PRIORVALUE(StageName)) = "Closed Lost",
        TEXT(PRIORVALUE(StageName)) = "Fechado Ganho",
        TEXT(PRIORVALUE(StageName)) = "Fechado Perdido"
    ),

    /* Libera se estiver alterando um dos campos permitidos */
    NOT(
        OR(
            ISCHANGED(LossReason__c),
            ISCHANGED(concorrente__c),
            ISCHANGED(OwnerId),
            ISCHANGED(Name),
            ISCHANGED(StageName),
            ISCHANGED(Analise_do_gestor__c)
        )
    )
)
